# Security Review of app.js

## Executive Summary

The application has **critical security vulnerabilities** stemming primarily from improper credential management rather than code-level issues in app.js itself. The Express application is relatively simple but lacks essential security practices.

---

## Critical Issues Found

### 1. **CRITICAL: Credentials in Version Control** ⚠️

**Location:** `.env.test` file
**Severity:** CRITICAL (OWASP A02:2021 – Cryptographic Failures)

**Issue:**
The `.env.test` file contains production credentials (marked as canary values):
- Database credentials with embedded password
- AWS access keys
- API keys (Anthropic, Stripe, Logfire)

**Why this is dangerous:**
- Credentials in `.git` history are **permanently compromised** — even if deleted, they remain in commit history
- Any person with repo access (now or in the future) can access production systems
- If repo is public, credentials are immediately exploited
- Automated scanners continuously monitor GitHub/GitLab for exposed credentials

**Recommendation:**
```bash
# 1. IMMEDIATELY rotate all credentials in .env.test
# 2. Never commit credentials:
echo ".env*" >> .gitignore
echo "*.env" >> .gitignore

# 3. Use a secrets manager instead:
# - AWS Secrets Manager
# - HashiCorp Vault
# - 1Password / Bitwarden
# - GitHub Secrets (for CI/CD)
# - Vercel/Netlify secrets (for deployed apps)

# 4. Use environment-specific config:
# .env.local (gitignored, local development)
# .env.example (committed, shows structure only)
```

**Example `.env.example`:**
```
DATABASE_URL=postgres://username:password@host:5432/database
AWS_ACCESS_KEY_ID=your_access_key_here
AWS_SECRET_ACCESS_KEY=your_secret_key_here
ANTHROPIC_API_KEY=your_api_key_here
```

---

### 2. **CRITICAL: No Input Validation** ⚠️

**Location:** `/users` endpoint (lines 11-15)
**Severity:** CRITICAL (OWASP A03:2021 – Injection)

**Issue:**
The `/users` endpoint returns hardcoded data but accepts **any query parameters without validation:**

```javascript
// Vulnerable - no validation
app.get('/users', (req, res) => {
  res.json([...]);
});

// Attacker can send anything:
// GET /users?filter=<script>alert('xss')</script>
// GET /users?page=../../etc/passwd
// No input is validated before use
```

**Recommendation:**
```javascript
const express = require('express');
const { query, validationResult } = require('express-validator');
const app = express();

// Add input validation middleware
app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('filter').optional().trim().escape(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { page = 1, limit = 10, filter } = req.query;

    // Now safe to use these values
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);
```

---

### 3. **HIGH: Missing HTTPS Enforcement**

**Location:** Entire application
**Severity:** HIGH (OWASP A02:2021 – Cryptographic Failures)

**Issue:**
Application runs on HTTP without HTTPS or redirect to HTTPS. Credentials in request headers are transmitted in plaintext.

**Recommendation:**
```javascript
const express = require('express');
const https = require('https');
const fs = require('fs');
const app = express();

// Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.get('host')}${req.url}`);
  }
  next();
});

// In production, use:
const options = {
  key: fs.readFileSync('/path/to/key.pem'),
  cert: fs.readFileSync('/path/to/cert.pem'),
};
https.createServer(options, app).listen(443);
```

---

### 4. **HIGH: No Authentication/Authorization**

**Location:** `/users` endpoint
**Severity:** HIGH (OWASP A01:2021 – Broken Access Control)

**Issue:**
Sensitive user data (emails, IDs) is exposed without any authentication checks.

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware to verify JWT token
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});
```

---

### 5. **HIGH: Missing Security Headers**

**Location:** All responses
**Severity:** HIGH (OWASP A05:2021 – Security Misconfiguration)

**Issue:**
No security headers to prevent common attacks (XSS, clickjacking, MIME type sniffing).

**Recommendation:**
```javascript
const helmet = require('helmet');
const app = express();

// Add security headers via helmet
app.use(helmet());

// Or manually:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');          // Prevent MIME type sniffing
  res.setHeader('X-Frame-Options', 'DENY');                    // Prevent clickjacking
  res.setHeader('X-XSS-Protection', '1; mode=block');          // Enable XSS filter
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains'); // Force HTTPS
  res.setHeader('Content-Security-Policy', "default-src 'self'"); // Prevent XSS
  next();
});
```

---

### 6. **MEDIUM: No Rate Limiting**

**Location:** All endpoints
**Severity:** MEDIUM (OWASP A04:2021 – Insecure Design)

**Issue:**
No protection against brute force, DoS, or API abuse attacks.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

// Apply to all routes
app.use(limiter);

// Or specific routes:
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter for auth endpoints
});
app.post('/login', authLimiter, (req, res) => { /* ... */ });
```

---

### 7. **MEDIUM: No Logging/Monitoring**

**Location:** All endpoints
**Severity:** MEDIUM (OWASP A09:2021 – Logging and Monitoring Failures)

**Issue:**
No access logs, error logs, or security event monitoring.

**Recommendation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Application logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Log suspicious activity
app.get('/users', (req, res) => {
  logger.info(`/users endpoint accessed from ${req.ip}`);
  res.json([...]);
});
```

---

### 8. **MEDIUM: No Error Handling/Information Disclosure**

**Location:** No error handler defined
**Severity:** MEDIUM (OWASP A01:2021 – Broken Access Control & Information Disclosure)

**Issue:**
Unhandled errors expose stack traces and internal details to attackers.

**Recommendation:**
```javascript
// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose internal details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(500).json({
    error: 'Internal Server Error',
    ...(isDevelopment && { details: err.message, stack: err.stack }),
  });
});

// Handle 404s
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 9. **MEDIUM: Missing CORS Configuration**

**Location:** No CORS middleware
**Severity:** MEDIUM (OWASP A01:2021 – Broken Access Control)

**Issue:**
Without CORS configuration, browser-based attacks from other domains are not restricted.

**Recommendation:**
```javascript
const cors = require('cors');

// Restrict CORS to trusted domains only
const allowedOrigins = [
  'https://app.example.com',
  'https://www.example.com',
];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

---

## Secure Implementation Example

Here's a hardened version of app.js:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// Trust proxy
app.set('trust proxy', 1);

// Security middleware
app.use(helmet());
app.use(morgan('combined'));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint with validation
app.get('/users',
  authenticateToken,
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('filter').optional().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Return user data only for authenticated users
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

