app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

function logSecurityEvent(event, details) {
  logger.warn({
    type: 'SECURITY_EVENT',
    event,
    ...details,
    timestamp: new Date().toISOString(),
  });
}

module.exports = app;
