      message: 'Invalid query parameters'
    });
  }

  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters based on validated input
  if (req.query.id) {
    users = users.filter(u => u.id === req.query.id);
  }
  if (req.query.name) {
    users = users.filter(u => u.name === req.query.name);
  }
  if (req.query.email) {
    users = users.filter(u => u.email === req.query.email);
  }

  const limit = Math.min(req.query.limit || 100, 100);
  res.json(users.slice(0, limit));
});
