    const verified = jwt.verify(token, process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', verifyToken, (req, res) => {
  // Now protected
  res.json([...]);
});
```

---

#### 4. **Missing Rate Limiting** ⚠️ MEDIUM
**Issue**: No rate limiting on endpoints
**OWASP**: A04:2021 – Insecure Design

**Problem**: Vulnerable to brute force, DDoS, and enumeration attacks:

**Recommendation**: Implement rate limiting:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});

app.use(limiter);

// Or specific routes
const strictLimiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 5
});

app.post('/login', strictLimiter, (req, res) => {
  // Protected endpoint
});
```

---

#### 5. **Missing CORS Configuration** ⚠️ MEDIUM
**Issue**: CORS headers not explicitly configured
**OWASP**: A01:2021 – Broken Access Control

**Problem**: By default, Express doesn't set CORS headers, which could allow unauthorized cross-origin requests:

**Recommendation**: Configure CORS explicitly:
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

---

#### 6. **Sensitive Data Exposure** ⚠️ MEDIUM
**Issue**: Hardcoded data and no encryption considerations
**OWASP**: A02:2021 – Cryptographic Failures

**Problem**: User emails are exposed in plaintext without encryption or access control

**Recommendation**:
```javascript
// Use environment variables for secrets
require('dotenv').config();

// Implement data masking for sensitive fields
const maskEmail = (email) => {
  const [user, domain] = email.split('@');
  return `${user.slice(0, 2)}***@${domain}`;
};

app.get('/users', verifyToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
    { id: 2, name: 'Bob', email: maskEmail('bob@example.com') }
  ];
  res.json(users);
});
```

---

#### 7. **Missing Error Handling & Information Disclosure** ⚠️ MEDIUM
**Issue**: No centralized error handling
**OWASP**: A05:2021 – Security Misconfiguration

**Problem**: Unhandled errors could expose stack traces and sensitive information

**Recommendation**: Implement proper error handling:
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack); // Log internally

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

#### 8. **No Logging or Monitoring** ⚠️ MEDIUM
**Issue**: Insufficient security logging
**OWASP**: A09:2021 – Logging and Monitoring Failures

**Recommendation**: Implement comprehensive logging:
```javascript
const morgan = require('morgan');

app.use(morgan('combined')); // HTTP request logging

// Add security event logging
const logSecurityEvent = (event, details) => {
  console.log(`[SECURITY] ${new Date().toISOString()} - ${event}:`, details);
};

app.use((req, res, next) => {
  // Log suspicious patterns
  if (req.query && JSON.stringify(req.query).length > 1000) {
    logSecurityEvent('LARGE_QUERY_DETECTED', {
      ip: req.ip,
      url: req.url
    });
  }
  next();
});
```

---

#### 9. **No HTTPS/TLS Configuration** ⚠️ HIGH
**Issue**: No mention of HTTPS
**OWASP**: A02:2021 – Cryptographic Failures

**Recommendation**: Use HTTPS in production:
```javascript
const https = require('https');
const fs = require('fs');

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000);
}
```

---

#### 10. **Missing Environment Configuration** ⚠️ MEDIUM
**Issue**: Hardcoded port and no environment-based configuration
**OWASP**: A05:2021 – Security Misconfiguration

**Recommendation**:
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (NODE_ENV === 'production') {
  // Enhanced security for production
  app.set('trust proxy', 1);
  app.disable('x-powered-by');
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

---

