### 6. ⚠️ MEDIUM: No Logging or Monitoring
**Severity:** MEDIUM  
**Category:** A09:2021 – Security Logging and Monitoring Failures

**Issue:**
No security event logging. Attackers can operate undetected.

**Risk:**
- Can't detect attacks
- No audit trail
- Cannot investigate incidents

**Remediation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// ✅ Configure structured logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ✅ Log HTTP requests
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
}));

// ✅ Log security events
app.use((req, res, next) => {
  // Log potentially suspicious activity
  if (req.query.search && req.query.search.length > 1000) {
    logger.warn('Possible injection attempt', {
      ip: req.ip,
      path: req.path,
      queryLength: req.query.search.length,
    });
  }
  next();
});

// ✅ Error handling with logging
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  res.status(500).json({ 
    error: 'Internal Server Error',
    requestId: req.id, // Track for investigation
  });
});
```

**Installation:**
```bash
npm install morgan winston
```

