- No HTTP security headers (CSP, HSTS, X-Frame-Options, etc.)
- Application is vulnerable to clickjacking, XSS, and other browser-based attacks

**Recommendations:**
```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Add security headers via helmet
app.use(helmet());

// Additional custom headers for strictness
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

